    <style>
      :root {
        color-scheme: dark;
        --bg: #080b12;
        --panel: #111827;
        --panel-strong: #172033;
        --text: #f8fafc;
        --muted: #b6c2d3;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --border: #314158;
        --focus: #facc15;
        --success: #86efac;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(56, 189, 248, 0.22), transparent 34rem),
          linear-gradient(135deg, #080b12 0%, #111827 52%, #0f172a 100%);
      }

      main {
        width: min(100% - 2rem, 54rem);
        margin: 0 auto;
        padding: 4rem 0;
      }

      .quiz-card {
        padding: clamp(1.25rem, 4vw, 2.5rem);
        border: 1px solid rgba(125, 211, 252, 0.22);
        border-radius: 1.5rem;
        background: rgba(17, 24, 39, 0.88);
        box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.45);
        backdrop-filter: blur(1rem);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.5rem);
        line-height: 1.05;
      }

      .intro {
        max-width: 44rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.0625rem;
      }

      .form-field {
        margin: 0 0 1.25rem;
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: linear-gradient(180deg, rgba(23, 32, 51, 0.96), rgba(17, 24, 39, 0.96));
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        padding: 0;
        font-size: 1.2rem;
        font-weight: 800;
      }

      .help-text {
        margin: 0.45rem 0 1rem;
        color: var(--muted);
      }

      .choices {
        display: grid;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .choice {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
        padding: 0.9rem 1rem;
        border: 1px solid rgba(148, 163, 184, 0.25);
        border-radius: 0.85rem;
        background: rgba(8, 11, 18, 0.46);
        color: var(--text);
        cursor: pointer;
        transition:
          border-color 160ms ease,
          background 160ms ease,
          transform 160ms ease;
      }

      .choice:hover {
        border-color: rgba(125, 211, 252, 0.72);
        background: rgba(14, 165, 233, 0.12);
        transform: translateY(-1px);
      }

      input[type="checkbox"] {
        width: 1.2rem;
        height: 1.2rem;
        margin: 0.12rem 0 0;
        accent-color: var(--accent-strong);
        flex: 0 0 auto;
      }

      :focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
        align-items: center;
        margin-top: 1.75rem;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.85rem 1.35rem;
        color: #04111d;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 0.75rem 1.75rem rgba(56, 189, 248, 0.24);
      }

      button:hover {
        filter: brightness(1.08);
      }

      #quiz-status {
        min-height: 1.5rem;
        color: var(--success);
        font-weight: 700;
      }
    </style>
  </head>
  <body>
    <main>
      <section class="quiz-card" aria-labelledby="quiz-title">
        <p class="eyebrow">Multiple answer quiz</p>
        <h1 id="quiz-title">Computer Languages</h1>
        <p class="intro">
          Select every answer that applies for each question, then submit your responses.
        </p>

        <form id="quiz-form">
          <div id="quiz-root"></div>

          <div class="actions">
            <button type="submit">Submit answers</button>
            <p id="quiz-status" role="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const quizQuestions = [
        {
          id: "compiled",
          prompt: "Which languages are commonly compiled before execution?",
          helpText: "Choose all answers that are typically compiled to native code or bytecode.",
          choices: ["C", "Java", "Python", "Rust"],
        },
        {
          id: "web",
          prompt: "Which languages are widely used for web development?",
          choices: ["JavaScript", "PHP", "HTML", "Swift"],
        },
        {
          id: "paradigms",
          prompt: "Which languages support object-oriented programming?",
          choices: ["Java", "C++", "Ruby", "SQL"],
        },
      ];

      function Choice({ questionId, choice }) {
        const id = `${questionId}-${choice.toLowerCase().replaceAll(" ", "-")}`;

        return `
          <label class="choice" for="${id}">
            <input type="checkbox" id="${id}" name="${questionId}" value="${choice}">
            <span>${choice}</span>
          </label>
        `;
      }

      function Question({ id, prompt, helpText, choices }, index) {
        const helpId = helpText ? `${id}-help` : "";
        const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${index + 1}. ${prompt}</legend>
              ${
                helpText
                  ? `<p class="help-text" id="${helpId}">${helpText}</p>`
                  : ""
              }
              <div class="choices">
                ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return questions.map((question, index) => Question(question, index)).join("");
      }

      document.getElementById("quiz-root").innerHTML = QuizApp({
        questions: quizQuestions,
      });

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const selectedCount = new FormData(event.currentTarget).entries().toArray?.().length;
        const fallbackCount = Array.from(
          event.currentTarget.querySelectorAll("input[type='checkbox']:checked")
        ).length;
        const count = selectedCount ?? fallbackCount;

        document.getElementById("quiz-status").textContent =
          `Submitted. You selected ${count} answer${count === 1 ? "" : "s"}.`;
      });
    </script>
  </body>
</html>
