    <main>
      <section class="quiz-card" aria-labelledby="quiz-title">
        <p class="eyebrow">Multiple answer quiz</p>
        <h1 id="quiz-title">Computer Languages</h1>
        <p class="intro">
          Select every answer that applies for each question, then submit your responses.
        </p>

        <form id="quiz-form">
          <div id="quiz-root"></div>

          <div class="actions">
            <button type="submit">Submit answers</button>
            <p id="quiz-status" role="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const quizQuestions = [
        {
          id: "compiled",
          prompt: "Which languages are commonly compiled before execution?",
          helpText: "Choose all answers that are typically compiled to native code or bytecode.",
          choices: ["C", "Java", "Python", "Rust"],
        },
        {
          id: "web",
          prompt: "Which languages are widely used for web development?",
          choices: ["JavaScript", "PHP", "HTML", "Swift"],
        },
        {
          id: "paradigms",
          prompt: "Which languages support object-oriented programming?",
          choices: ["Java", "C++", "Ruby", "SQL"],
        },
      ];

      function Choice({ questionId, choice }) {
        const id = `${questionId}-${choice.toLowerCase().replaceAll(" ", "-")}`;

        return `
          <label class="choice" for="${id}">
            <input type="checkbox" id="${id}" name="${questionId}" value="${choice}">
            <span>${choice}</span>
          </label>
        `;
      }

      function Question({ id, prompt, helpText, choices }, index) {
        const helpId = helpText ? `${id}-help` : "";
        const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${index + 1}. ${prompt}</legend>
              ${
                helpText
                  ? `<p class="help-text" id="${helpId}">${helpText}</p>`
                  : ""
              }
              <div class="choices">
                ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return questions.map((question, index) => Question(question, index)).join("");
      }

      document.getElementById("quiz-root").innerHTML = QuizApp({
        questions: quizQuestions,
      });

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const count = Array.from(
          event.currentTarget.querySelectorAll("input[type='checkbox']:checked")
        ).length;

        document.getElementById("quiz-status").textContent =
          `Submitted. You selected ${count} answer${count === 1 ? "" : "s"}.`;
      });
    </script>
  </body>
</html>
